import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Portfolio Backtester and Analyzer","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/portfolio-analytics.md","filePath":"new-features/portfolio-analytics.md"}'),i={name:"new-features/portfolio-analytics.md"};function l(s,e,n,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="portfolio-backtester-and-analyzer" tabindex="-1">Portfolio Backtester and Analyzer <a class="header-anchor" href="#portfolio-backtester-and-analyzer" aria-label="Permalink to &quot;Portfolio Backtester and Analyzer&quot;">​</a></h1><p>Tradeboard provides two authenticated, read-only portfolio workflows:</p><ul><li><strong>Portfolio Backtester</strong> simulates a target allocation over a historical window.</li><li><strong>Portfolio Analyzer</strong> reads the holdings currently reported by the connected broker, weights them by current market value, and tests how that allocation would have behaved over a selected lookback.</li></ul><p>Neither workflow places, modifies, or cancels an order.</p><h2 id="before-you-start" tabindex="-1">Before You Start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before You Start&quot;">​</a></h2><ul><li>Create an Tradeboard API key.</li><li>For the default <strong>Historify</strong> source, ingest daily history for every holding and the selected benchmark.</li><li>For the <strong>Broker API</strong> source, log in to the broker and confirm that its history API covers the required symbols and dates.</li><li>The engine supports long-only NSE/BSE cash equities and ETFs. It does not model derivatives, short positions, or a separate cash sleeve.</li></ul><h2 id="backtest-a-portfolio" tabindex="-1">Backtest a Portfolio <a class="header-anchor" href="#backtest-a-portfolio" aria-label="Permalink to &quot;Backtest a Portfolio&quot;">​</a></h2><ol><li>Open <code>/portfolio-backtester</code>.</li><li>Add up to 50 unique NSE/BSE holdings and assign a positive weight to each. Weights can be percentages or fractions; Tradeboard normalizes their ratio.</li><li>Choose the date range and optional index benchmark.</li><li>Choose a history source: <ul><li><code>db</code> reads the local Historify store in one multi-symbol query.</li><li><code>api</code> calls the active broker&#39;s history service sequentially.</li></ul></li><li>Select <code>never</code>, <code>monthly</code>, <code>quarterly</code>, or <code>yearly</code> rebalancing. An optional drift band can trigger an earlier rebalance.</li><li>Configure capital, risk-free rate, slippage, and either the Indian delivery-cost schedule or a flat basis-point cost.</li><li>Run the backtest. The results page uses one internally consistent result object; changing tabs does not rerun the simulation.</li></ol><h2 id="understand-the-results" tabindex="-1">Understand the Results <a class="header-anchor" href="#understand-the-results" aria-label="Permalink to &quot;Understand the Results&quot;">​</a></h2><p>The analysis can include:</p><ul><li>portfolio and benchmark equity curves;</li><li>returns, volatility, drawdown, Sharpe/Sortino, capture, and rolling statistics;</li><li>holding contributions and trailing returns;</li><li>correlation, effective-holdings concentration, co-movement groups, and allocation drift;</li><li>realized trading costs, turnover, and rebalancing dates;</li><li>walk-forward windows, Monte Carlo paths, crisis periods, attribution, and seasonality;</li><li>a portfolio-health grade whose inputs, formulas, and pillar weights are returned with the score.</li></ul><p>Use <strong>Download tearsheet</strong> to export the same model as a self-contained <code>portfolio-tearsheet.html</code> file.</p><h2 id="analyze-current-holdings" tabindex="-1">Analyze Current Holdings <a class="header-anchor" href="#analyze-current-holdings" aria-label="Permalink to &quot;Analyze Current Holdings&quot;">​</a></h2><ol><li>Log in to the broker.</li><li>Open <code>/portfolio-analyzer</code>.</li><li>Choose a 60-3650 day lookback, history source, benchmark, and risk-free rate.</li><li>Tradeboard loads usable broker holdings, calculates market-value weights, and runs the same analytics engine.</li></ol><p>Unsupported exchanges remain visible in the holdings summary and are listed as skipped. This is a current-allocation historical scenario, not an account-performance report: holdings data does not reveal when each lot was bought or the investor&#39;s cash flows.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Results use close-to-close price returns. Dividends are absent unless the selected history source embeds an adjusted series.</li><li>Missing holding history fails the run instead of silently dropping the asset.</li><li>Missing benchmark history degrades benchmark-relative sections but does not invalidate the portfolio calculation.</li><li>Results depend on history quality, the chosen allocation, and cost assumptions. They are not a forecast or investment advice.</li></ul><p>See the <a href="./../api-documentation/v1/portfolio">Portfolio API</a> for automation and <a href="./../developers/design-documentation/55-portfolio-analytics">Portfolio Analytics Architecture</a> for implementation boundaries.</p>',18)])])}const f=o(i,[["render",l]]);export{p as __pageData,f as default};
